      "causa_raiz": "Chamada repetitiva a GameObject.FindObjectsOfType<GameObject>() dentro do método Update(). Esse método faz uma varredura completa e linear na hierarquia de objetos da cena no lado nativo da engine, alocando um array novo gerenciado a cada iteração, consumindo dezenas de milissegundos de CPU por quadro.",
      "codigo_refatorado": "using System;\\nusing System.Collections.Generic;\\nusing System.Text;\\nusing UnityEngine;\\n\\nnamespace PerformanceAdvisor.StressTest\\n{\\n    public class StressTestScene : MonoBehaviour\\n    {\\n        public bool stressGc = false;\\n        public bool stressCpu = false;\\n        public bool stressDraw = false;\\n\\n        public GameObject testPrefab;\\n        [Range(1, 20)] public float spawnRadius = 10f;\\n        [Range(1, 50)] public int cubesPerFrame = 1;\\n        public bool useUniqueMaterials = false;\\n        [Range(1, 512)] public int cpuScansPerFrame = 1;\\n        public int emptyObjects = 0;\\n        public int gcConcatIterations = 1000;\\n        public int gcArrayAllocs = 0;\\n        public int overdrawLayers = 0;\\n        public Material overdrawMaterial;\\n        [Range(0, 2000)] public int prepopulateCount = 0;\\n\\n        private readonly StringBuilder _stringBuilder = new StringBuilder(4096);\\n        private MaterialPropertyBlock _propBlock;\\n        private static readonly int ColorPropId = Shader.PropertyToID(\\\"_Color\\\");\\n        private readonly List<GameObject> _trackedObjects = new List<GameObject>();\\n\\n        private void Awake()\\n        {\\n            _propBlock = new MaterialPropertyBlock();\\n        }\\n\\n        private void Start()\\n        {\\n            if (prepopulateCount > 0 && testPrefab != null)\\n            {\\n                for (int i = 0; i < prepopulateCount; i++)\\n                {\\n                    SpawnOne();\\n                }\\n            }\\n\\n            for (int i = 0; i < emptyObjects; i++)\\n            {\\n                var go = new GameObject(\\\"Empty_\\\" + i);\\n                _trackedObjects.Add(go);\\n            }\\n\\n            if (overdrawLayers > 0 && overdrawMaterial != null)\\n            {\\n                BuildOverdrawLayers();\\n            }\\n        }\\n\\n        private void BuildOverdrawLayers()\\n        {\\n            Camera cam = Camera.main;\\n            if (cam == null) return;\\n\\n            float halfFov = cam.fieldOfView * 0.5f * Mathf.Deg2Rad;\\n            for (int i = 0; i < overdrawLayers; i++)\\n            {\\n                float d = cam.nearClipPlane + 0.05f + i * 0.001f;\\n                float h = 2f * d * Mathf.Tan(halfFov) * 1.1f;\\n                var quad = GameObject.CreatePrimitive(PrimitiveType.Quad);\\n                Destroy(quad.GetComponent<Collider>());\\n                quad.name = \\\"Overdraw_\\\" + i;\\n                quad.transform.SetParent(cam.transform, false);\\n                quad.transform.localPosition = new Vector3(0f, 0f, d);\\n                quad.transform.localScale = new Vector3(h * cam.aspect, h, 1f);\\n                quad.GetComponent<Renderer>().sharedMaterial = overdrawMaterial;\\n            }\\n        }\\n\\n        private void Update()\\n        {\\n            if (stressGc)\\n            {\\n                _stringBuilder.Clear();\\n                for (int i = 0; i < gcConcatIterations; i++)\\n                {\\n                    _stringBuilder.Append(i);\\n                }\\n            }\\n\\n            if (stressCpu)\\n            {\\n                for (int k = 0; k < cpuScansPerFrame; k++)\\n                {\\n                    int count = _trackedObjects.Count;\\n                    for (int j = 0; j < count; j++)\\n                    {\\n                        var item = _trackedObjects[j];\\n                        if (item != null)\\n                        {\\n                            var pos = item.transform.position;\\n                        }\\n                    }\\n                }\\n            }\\n\\n            if (stressDraw && testPrefab != null)\\n            {\\n                int n = Mathf.Max(1, cubesPerFrame);\\n                for (int i = 0; i < n; i++)\\n                {\\n                    SpawnOne();\\n                }\\n            }\\n        }\\n\\n        private void SpawnOne()\\n        {\\n            var clone = Instantiate(\\n                testPrefab,\\n                UnityEngine.Random.insideUnitSphere * spawnRadius,\\n                Quaternion.identity);\\n\\n            _trackedObjects.Add(clone);\\n\\n            if (useUniqueMaterials)\\n            {\\n                var rend = clone.GetComponent<Renderer>();\\n                if (rend != null)\\n                {\\n                    rend.GetPropertyBlock(_propBlock);\\n                    _propBlock.SetColor(ColorPropId, new Color(\\n                        UnityEngine.Random.value,\\n                        UnityEngine.Random.value,\\n                        UnityEngine.Random.value));\\n                    rend.SetPropertyBlock(_propBlock);\\n                }\\n            }\\n        }\\n    }\\n}\",\\n      \"explicacao_didatica\": \"Usar FindObjectsOfType a cada frame é como pedir para alguém ler um catálogo telefônico inteiro do zero a cada segundo para encontrar nomes. Em vez de varrer a cena toda procurando os objetos repetidamente, mantemos uma lista interna e adicionamos os objetos nela conforme são criados. Assim, o processador acessa a lista diretamente na memória sem vasculhar o jogo todo.\"\\n    },\\n    {\\n      \"tipo\": \"GC\",\\n      \"causa_raiz\": \"Concatenação repetida de strings via operador '+' (s += i.ToString()) e alocação frequente de arrays no loop de Update. Cada concatenação de string cria um novo objeto na memória Heap gerenciada, gerando mais de 5 MB de lixo por frame e obrigando o Garbage Collector a congelar o jogo por ~16ms para coletar o lixo residual.\",\\n      \"codigo_refatorado\": \"using System;\\nusing System.Collections.Generic;\\nusing System.Text;\\nusing UnityEngine;\\n\\nnamespace PerformanceAdvisor.StressTest\\n{\\n    public class StressTestScene : MonoBehaviour\\n    {\\n        public bool stressGc = false;\\n        public bool stressCpu = false;\\n        public bool stressDraw = false;\\n\\n        public GameObject testPrefab;\\n        [Range(1, 20)] public float spawnRadius = 10f;\\n        [Range(1, 50)] public int cubesPerFrame = 1;\\n        public bool useUniqueMaterials = false;\\n        [Range(1, 512)] public int cpuScansPerFrame = 1;\\n        public int emptyObjects = 0;\\n        public int gcConcatIterations = 1000;\\n        public int gcArrayAllocs = 0;\\n        public int overdrawLayers = 0;\\n        public Material overdrawMaterial;\\n        [Range(0, 2000)] public int prepopulateCount = 0;\\n\\n        private readonly StringBuilder _stringBuilder = new StringBuilder(4096);\\n        private MaterialPropertyBlock _propBlock;\\n        private static readonly int ColorPropId = Shader.PropertyToID(\\\"_Color\\\");\\n        private readonly List<GameObject> _trackedObjects = new List<GameObject>();\\n\\n        private void Awake()\\n        {\\n            _propBlock = new MaterialPropertyBlock();\\n        }\\n\\n        private void Start()\\n        {\\n            if (prepopulateCount > 0 && testPrefab != null)\\n            {\\n                for (int i = 0; i < prepopulateCount; i++)\\n                {\\n                    SpawnOne();\\n                }\\n            }\\n\\n            for (int i = 0; i < emptyObjects; i++)\\n            {\\n                var go = new GameObject(\\\"Empty_\\\" + i);\\n                _trackedObjects.Add(go);\\n            }\\n\\n            if (overdrawLayers > 0 && overdrawMaterial != null)\\n            {\\n                BuildOverdrawLayers();\\n            }\\n        }\\n\\n        private void BuildOverdrawLayers()\\n        {\\n            Camera cam = Camera.main;\\n            if (cam == null) return;\\n\\n            float halfFov = cam.fieldOfView * 0.5f * Mathf.Deg2Rad;\\n            for (int i = 0; i < overdrawLayers; i++)\\n            {\\n                float d = cam.nearClipPlane + 0.05f + i * 0.001f;\\n                float h = 2f * d * Mathf.Tan(halfFov) * 1.1f;\\n                var quad = GameObject.CreatePrimitive(PrimitiveType.Quad);\\n                Destroy(quad.GetComponent<Collider>());\\n                quad.name = \\\"Overdraw_\\\" + i;\\n                quad.transform.SetParent(cam.transform, false);\\n                quad.transform.localPosition = new Vector3(0f, 0f, d);\\n                quad.transform.localScale = new Vector3(h * cam.aspect, h, 1f);\\n                quad.GetComponent<Renderer>().sharedMaterial = overdrawMaterial;\\n            }\\n        }\\n\\n        private void Update()\\n        {\\n            if (stressGc)\\n            {\\n                _stringBuilder.Clear();\\n                for (int i = 0; i < gcConcatIterations; i++)\\n                {\\n                    _stringBuilder.Append(i);\\n                }\\n            }\\n\\n            if (stressCpu)\\n            {\\n                for (int k = 0; k < cpuScansPerFrame; k++)\\n                {\\n                    int count = _trackedObjects.Count;\\n                    for (int j = 0; j < count; j++)\\n                    {\\n                        var item = _trackedObjects[j];\\n                        if (item != null)\\n                        {\\n                            var pos = item.transform.position;\\n                        }\\n                    }\\n                }\\n            }\\n\\n            if (stressDraw && testPrefab != null)\\n            {\\n                int n = Mathf.Max(1, cubesPerFrame);\\n                for (int i = 0; i < n; i++)\\n                {\\n                    SpawnOne();\\n                }\\n            }\\n        }\\n\\n        private void SpawnOne()\\n        {\\n            var clone = Instantiate(\\n                testPrefab,\\n                UnityEngine.Random.insideUnitSphere * spawnRadius,\\n                Quaternion.identity);\\n\\n            _trackedObjects.Add(clone);\\n\\n            if (useUniqueMaterials)\\n            {\\n                var rend = clone.GetComponent<Renderer>();\\n                if (rend != null)\\n                {\\n                    rend.GetPropertyBlock(_propBlock);\\n                    _propBlock.SetColor(ColorPropId, new Color(\\n                        UnityEngine.Random.value,\\n                        UnityEngine.Random.value,\\n                        UnityEngine.Random.value));\\n                    rend.SetPropertyBlock(_propBlock);\\n                }\\n            }\\n        }\\n    }\\n}\",\\n      \"explicacao_didatica\": \"Textos (strings) no C# não podem ser alterados após criados. Quando fazemos 's += algo', o C# cria um novo texto na memória e descarta o anterior. Fazer isso milhares de vezes por quadro acumula megabytes de texto descartado. O Garbage Collector (o 'caminhão de lixo' da memória) precisa pausar o jogo para limpar essa sujeira, causando travamentos. Ao usar o StringBuilder e reaproveitar memória, evitamos criar e jogar fora texto a todo momento.\"\\n    }\\n  ],\\n  \"dicas_level_design\": null\\n}"
    ,
  "explicacao_didatica": "O código refatorado otimiza tanto o consumo de CPU quanto a geração de lixo na memória. Eliminamos o uso abusivo de FindObjectsOfType e evitamos concatenação desenfreada de strings através do reaproveitamento de buffers e listas pré-existentes, além de trocar a clonagem de materiais em tempo de execução por MaterialPropertyBlock."
}
]
